verify.cmd:
node -e 'const fs=require("fs"),p=require("path"),os=require("os"),cp=require("child_process")
const fail=(m)=>{console.error("HYG-140 FAILED: "+m);process.exit(1)}
const R=process.cwd()
const pkg=JSON.parse(fs.readFileSync("package.json","utf8"))
if(!String(pkg.scripts.prebuild||"").includes("scripts/snapshot-turbopack-cache.mjs"))fail("prebuild does not snapshot the compiler cache a build restores, so an over-budget build can only trim it and the next build compiles cold")
if(!String(pkg.scripts.postbuild||"").includes("scripts/check-cache-budget.mjs"))fail("postbuild no longer runs check:cache-budget")
const gateSrc=fs.readFileSync("scripts/check-cache-budget.mjs","utf8")
const lim=Number((/^const HOLD_LIMIT = (\d+)$/m.exec(gateSrc)||[])[1])
if(!(lim>=1&&lim<=12))fail("HOLD_LIMIT is "+lim+", so a held generation is never refreshed or never held")
const cycle=(heldBefore)=>{
const d=fs.mkdtempSync(p.join(os.tmpdir(),"hyg140-"))
const c=p.join(d,".next","cache"),v=p.join(c,"turbopack","v1")
fs.mkdirSync(v,{recursive:true})
fs.writeFileSync(p.join(v,"00000001.sst"),"restored")
fs.writeFileSync(p.join(v,"CURRENT"),"restored")
if(heldBefore)fs.writeFileSync(p.join(c,"turbopack-held.json"),JSON.stringify({held:heldBefore}))
const run=(f)=>cp.spawnSync(process.execPath,[p.join(R,f)],{cwd:d,encoding:"utf8"})
run("scripts/snapshot-turbopack-cache.mjs")
const fd=fs.openSync(p.join(v,"00000002.sst"),"w");fs.ftruncateSync(fd,8e9);fs.closeSync(fd)
fs.writeFileSync(p.join(v,"CURRENT"),"grown")
const g=run("scripts/check-cache-budget.mjs")
const cur=fs.existsSync(p.join(v,"CURRENT"))?fs.readFileSync(p.join(v,"CURRENT"),"utf8"):"gone"
const st=p.join(c,"turbopack-held.json")
const r={status:g.status,cur,snap:fs.existsSync(p.join(c,"turbopack-restored")),held:fs.existsSync(st)?JSON.parse(fs.readFileSync(st,"utf8")).held:0}
fs.rmSync(d,{recursive:true,force:true})
return r}
const a=cycle(0)
if(a.status!==0)fail("the gate exited "+a.status+" on a build whose compiler cache outgrew the trim point")
if(a.cur!=="restored")fail("a build whose compiler cache outgrew the trim point uploads "+(a.cur==="gone"?"no compiler cache (the next build compiles cold)":"its own grown cache")+" instead of the generation it restored")
if(a.held!==1)fail("the hold is not counted, so nothing refreshes a frozen generation")
const b=cycle(lim)
if(b.snap||a.snap)fail("the restored snapshot is left in .next/cache, so Vercel packs the compiler cache twice")
if(b.cur!=="gone"||b.held!==0)fail("after HOLD_LIMIT holds in a row the gate still holds, so the compiler cache never refreshes")
console.log("HYG-140 ok: held at the restored generation, counted 1, refreshed after "+lim)'
